package com.bank.consolidation;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class MergeDedupeDemo {
    private static final Logger log = Logger.getLogger("Consolidation");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> branchA = List.of(
            new Employee(1, "Rajesh", "IT", 1000000),
            new Employee(2, "Amit", "IT", 600000));
        List<Employee> branchB = List.of(
            new Employee(2, "Amit", "IT", 600000),     // duplicate id 2
            new Employee(3, "Priya", "Sales", 900000));
        ConsolidationService service = new ConsolidationService();

        Map<String, Double> avg = service.avgSalaryByDeptDeduped(branchA, branchB);
        log.info(() -> "Avg salary by dept (deduped): " + avg);
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final int id;
    private final String name;
    private final String department;
    private final double salary;
    Employee(int id, String name, String department, double salary) {
            this.id = id;
            this.name = name
            this.department = department
            this.salary = salary;
    }
    int getId() { return id; }
    String getDepartment() { return department; }
    double getSalary() { return salary; }
}

// ─── Would be in service/ConsolidationService.java ───
class ConsolidationService {
    Map<String, Double> avgSalaryByDeptDeduped(List<Employee> a, List<Employee> b) {
        Collection<Employee> unique = java.util.stream.Stream.concat(a.stream(), b.stream())
            .collect(toMap(Employee::getId, e -> e, (x, y) -> x))  // dedupe BY ID (keep first)
            .values();
        return unique.stream()
            .collect(groupingBy(Employee::getDepartment,
                averagingDouble(Employee::getSalary)));             // avg per dept
    }
}
